#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub enum Severity {
    #[default]
    CRITICAL = 0,
    ERROR = 1,
    WARN = 2,
    INFO = 3,
    DEBUG = 4,
    TRACE = 5,
}

impl From<Severity> for FbsSeverity {
    fn from(val: Severity) -> Self {
        match val {
            Severity::CRITICAL => FbsSeverity::CRITICAL,
            Severity::ERROR => FbsSeverity::ERROR,
            Severity::WARN => FbsSeverity::WARN,
            Severity::INFO => FbsSeverity::INFO,
            Severity::DEBUG => FbsSeverity::DEBUG,
            Severity::TRACE => FbsSeverity::TRACE,
        }
    }
}

impl From<FbsSeverity> for Severity {
    fn from(fbs: FbsSeverity) -> Self {
        match fbs.0 {
            0 => Self::CRITICAL,
            1 => Self::ERROR,
            2 => Self::WARN,
            3 => Self::INFO,
            4 => Self::DEBUG,
            5 => Self::TRACE,
            _ => panic!("Invalid value {} when constructing Severity", fbs.0),
        }
    }
}

#[derive(Default, PartialEq, Debug, Clone)]
pub struct Label {
    pub key: String,
    pub value: String,
}

impl Label {
    pub fn serialize_to<'a>(
        &self,
        builder: &mut flatbuffers::FlatBufferBuilder<'a>,
    ) -> flatbuffers::WIPOffset<FbsLabel<'a>> {
        use crate::types::generated::log_generated::LabelBuilder as FbsLabelBuilder;

        let key_offset = builder.create_string(&self.key);
        let value_offset = builder.create_string(&self.value);

        let mut bldr = FbsLabelBuilder::new(builder);
        bldr.add_key(key_offset);
        bldr.add_value(value_offset);
        bldr.finish()
    }
}

impl From<FbsLabel<'_>> for Label {
    fn from(fbs: FbsLabel<'_>) -> Self {
        let key = fbs.key().to_owned();
        let value = fbs.value().to_owned();
        Self { key, value }
    }
}

impl TryFrom<&[u8]> for Label {
    type Error = flatbuffers::InvalidFlatbuffer;
    fn try_from(bytes: &[u8]) -> Result<Self, Self::Error> {
        let fbs = flatbuffers::size_prefixed_root::<FbsLabel>(bytes)?;
        Ok(Self::from(fbs))
    }
}

impl From<Label> for Vec<u8> {
    fn from(obj: Label) -> Self {
        let mut bldr = flatbuffers::FlatBufferBuilder::new();
        let offset = obj.serialize_to(&mut bldr);
        bldr.finish_size_prefixed(offset, None);
        bldr.finished_data().to_vec()
    }
}

#[derive(Default, PartialEq, Debug, Clone)]
pub struct Log {
    pub labels: Vec<Label>,
    pub pairs: Vec<Pair>,
    pub timestamp: i64,
}

impl Log {
    pub fn serialize_to<'a>(
        &self,
        builder: &mut flatbuffers::FlatBufferBuilder<'a>,
    ) -> flatbuffers::WIPOffset<FbsLog<'a>> {
        use crate::types::generated::log_generated::LogBuilder as FbsLogBuilder;

        let mut labels_offsets = Vec::with_capacity(self.labels.len());
        for val in self.labels.iter() {
            let offset = val.serialize_to(builder);
            labels_offsets.push(offset);
        }
        let labels_offset = builder.create_vector(&labels_offsets);
        let mut pairs_offsets = Vec::with_capacity(self.pairs.len());
        for val in self.pairs.iter() {
            let offset = val.serialize_to(builder);
            pairs_offsets.push(offset);
        }
        let pairs_offset = builder.create_vector(&pairs_offsets);

        let mut bldr = FbsLogBuilder::new(builder);
        bldr.add_labels(labels_offset);
        bldr.add_pairs(pairs_offset);
        bldr.add_timestamp(self.timestamp);
        bldr.finish()
    }
}

impl From<FbsLog<'_>> for Log {
    fn from(fbs: FbsLog<'_>) -> Self {
        let mut labels = Vec::new();
        for elem in fbs.labels() {
            labels.push(elem.into());
        }

        let mut pairs = Vec::new();
        for elem in fbs.pairs() {
            pairs.push(elem.into());
        }

        let timestamp = fbs.timestamp();
        Self {
            labels,
            pairs,
            timestamp,
        }
    }
}

impl TryFrom<&[u8]> for Log {
    type Error = flatbuffers::InvalidFlatbuffer;
    fn try_from(bytes: &[u8]) -> Result<Self, Self::Error> {
        let fbs = flatbuffers::size_prefixed_root::<FbsLog>(bytes)?;
        Ok(Self::from(fbs))
    }
}

impl From<Log> for Vec<u8> {
    fn from(obj: Log) -> Self {
        let mut bldr = flatbuffers::FlatBufferBuilder::new();
        let offset = obj.serialize_to(&mut bldr);
        bldr.finish_size_prefixed(offset, None);
        bldr.finished_data().to_vec()
    }
}

