        let key_offset = builder.create_string(&self.key);
        let (value_offset, value_ty) = self.value.serialize_to(builder);

        let mut bldr = FbsPairBuilder::new(builder);
        bldr.add_key(key_offset);
        bldr.add_value(value_offset);
        bldr.add_value_type(value_ty);
